  "devEnv.warningBodySrt": "AI가 모든 채팅에서 팀 서버의 어떤 프로그램이든 실행할 수 있어요. 명령은 채팅한 사람이 읽을 수 있는 모든 팀 폴더를 읽을 수 있어요. 쓰기는 그 채팅의 프로젝트 폴더와 그 사람의 개인 폴더에만 할 수 있어요. 샌드박스가 서버 데이터, 비밀 값, 다른 사람의 개인 폴더, 그 사람이 열 수 없는 폴더를 숨겨요.\n- 명령은 허용된 사이트를 통해 데이터를 밖으로 보낼 수 있어요. GitHub, npm, PyPI는 업로드를 받으므로, 명령이 그 사람이 읽을 수 있는 모든 파일을 보낼 수 있어요.\n- 각 사람은 채팅에서 물어볼 때 자기 명령에 쓸 사이트를 더 허용하거나, 자기에게만 전체 인터넷을 켤 수 있어요. 그러면 그 사람의 명령은 그 사이트에도 데이터를 보낼 수 있어요. 관리자 단계는 없어요.\n- 명령은 그 사람이 읽을 수 있는 파일을 더 많은 사람이 보는 프로젝트 폴더로 복사할 수 있어요.\n- 명령이 그 사람의 개인 폴더에서 바꾼 파일은 변경 기록과 이전 버전이 없어요.\n- 프로젝트 폴더에 쓸 수 있는 사람은 모두 같은 폴더를 써요. 한 사람의 변경이 다른 사람의 다음 명령에 영향을 줘요.\n- 로그인이 없어요. git push 같은 명령은 자기 컴퓨터에서 하세요.\n- 메모리를 너무 많이 쓰는 실행은 멈춰요. 팀의 무거운 작업은 대기열에서 기다려요.\n- 명령은 활동 기록에 남아요.\n이 기능은 실험이고 언제든 끌 수 있어요.",
