  'teamSettings.browserAllowAllHint': '데스크톱 앱의 앱 안 브라우저 설정이에요. 끄면 팀의 누구도(관리자 포함) 개인 설정에서 고를 수 없고, 이미 켠 사람도 "새 사이트마다 묻기"로 돌아가요. 사내망 주소, 비밀번호·카드 입력란 보호는 어느 쪽이든 그대로예요.',
  'speech.title': "음성 입력",
  'speech.desc': "채팅의 마이크 버튼이 말을 글로 바꾸는 방법이에요.",
  'speech.provider': "받아쓰기",
  'speech.off': "끄기",
  'speech.openrouter': "OpenRouter (클라우드)",
  'speech.local': "이 서버에서 (비공개)",
  'speech.localHint': "음성이 이 서버 밖으로 나가지 않아요. 작은 서버에서는 느려요(짧은 녹음에 10초–1분).",
  'speech.localMissing': "이 서버에 {tools} 프로그램이 없어서 음성 입력이 꺼져 있어요.",
  'speech.mediaTranscripts': "영상 소리를 글로 바꾸기",
  'speech.mediaTranscriptsLocal': "AI가 영상·오디오 파일(회의 녹음 등)을 읽을 때 소리를 이 서버에서 글로 바꿔요. 소리는 서버 밖으로 나가지 않아요. 소리를 {sec}초씩 나눠 바꾸는데, 한 번 읽을 때 시간 안에 끝나는 만큼만 바꾸고 다시 읽으면 그다음부터 이어서 바꿔요.",
  'speech.mediaTranscriptsSmall': "이 서버에서는 소리를 글로 바꾸는 데 오래 걸려서 꺼 두었어요(CPU 코어 {cores}개). 관리자가 켤 수 있고, 꺼져 있어도 AI는 영상의 장면을 볼 수 있어요.",
  'speech.mediaTranscriptsSpeedMin': "이 서버에서 재 보니 소리 1분을 바꾸는 데 약 {n}분 걸려요.",
  'speech.mediaTranscriptsSpeedSec': "이 서버에서 재 보니 소리 1분을 바꾸는 데 약 {n}초 걸려요.",
  'speech.mediaTranscriptsHosted': "이 호스팅 서버에서는 한 번 읽을 때 새 소리를 {min}분까지만 바꿔요.",
  'speech.mediaTranscriptsOpenRouter': "AI가 영상·오디오 파일(회의 녹음, 고객 통화, 교육 영상 등)을 읽을 때 그 소리를 OpenRouter와 그 제공사로 보내 글로 바꿔요. 음성 입력과는 다른 자료예요. 데이터를 남기지 않도록 요청하지만 우리가 강제할 수는 없어요. 기밀 대화에서는 보내지 않아요.",
  'speech.privacy': "음성이 OpenRouter와 그 제공사로 가요. 데이터를 남기지 않도록(zero data retention) 요청해요.",
  'speech.model': "모델",
  'speech.key': "OpenRouter API 키",
  'speech.keySet': "키가 있어요(…{hint}).",
  'speech.keyNone': "아직 키가 없어요. 키를 넣기 전까지 음성 입력은 꺼져 있어요.",
  'speech.getKey': "openrouter.ai/keys에서 키 받기",
  'speech.price': "OpenRouter 요금은 녹음 1시간에 약 $0.1예요.",
  'speech.saveKey': "키 저장",
  'speech.removeKey': "키 지우기",
  'speech.removeConfirm': "OpenRouter 키를 지울까요? 새 키를 넣을 때까지 음성 입력이 멈춰요.",
  'speech.keySaved': "키를 저장했어요",
  'speech.keyRemoved': "키를 지웠어요",
  'speech.mediaTranscriptsHostedKey': "AI가 영상·오디오 파일(회의 녹음 등)을 읽을 때 그 소리를 트리나 호스팅 받아쓰기로 글로 바꿔요. 소리는 OpenRouter를 거쳐 미국의 DeepInfra(안 되면 Groq)로 가고, 두 곳 모두 데이터를 남기지 않아요. 음성 입력과 같은 무료 시간을 써요. 기밀 대화에서는 보내지 않아요.",
  'speech.privacyHosted': "음성은 OpenRouter를 거쳐 미국의 DeepInfra(안 되면 Groq)로 가서 글로 바뀌어요. 데이터를 남기지 않는(zero data retention) 곳으로만 가요.",
  'speech.hostedKeyInUse': "트리나 호스팅이 준 키로 받아쓰고 있어요. 팀 키를 넣으면 그 키를 먼저 쓰고, 그때는 시간 제한이 없어요(요금은 팀의 OpenRouter 계정에 나가요).",
  'speech.hostedUsage': "이번 달 무료 받아쓰기 {free}시간 중 {used}시간 사용",
  'speech.hostedOwnKey': "팀 키로 받아쓰고 있어서 무료 시간은 줄지 않아요.",
  'speech.removeConfirmHosted': "팀 OpenRouter 키를 지울까요? 그다음부터는 트리나 호스팅 키로 이번 달 무료 시간 안에서 받아써요.",
  'teamSettings.stable': '안정',
  'teamSettings.beta': '베타',
  'teamSettings.updateWindow': '자동 업데이트 시간',
  'teamSettings.updateWindowHint': '예: 02:00-05:00(팀 시간대). 시는 00–23, 분은 00–59. 비워 두면 03:00-05:00이에요. 이 서버는 이 시간 안에서, 진행 중인 답변이 없을 때만 스스로 업데이트해요.',
  'teamSettings.updateWindowLegacy': '지금 적용 중: {window}({zone}). 예전에 서버 맥에서 "teamax update time"으로 정한 시간이에요. 여기에 시간을 저장하면 그 시간이 먼저 적용되고, 칸을 다시 비우면 이 시간으로 돌아가요. 02:00-05:00처럼 쓰고, 시는 00–23, 분은 00–59예요.',
  'teamSettings.updateWindowBad': 'HH:mm-HH:mm 형식으로 시는 00–23, 분은 00–59로 입력해 주세요.',

