  "kg.desc": "AI가 팀 파일에서 찾도록 도와요. 문서에 무엇이 쓰여 있는지, 코드가 어떻게 이어지는지요. 파일이 바뀌면 저절로 갱신돼요.",
  "kg.enable": "코드 지도",
  "kg.enableDesc": "AI가 코드 프로젝트의 함수와 그 연결을 찾아봐요. 각자 열 수 있는 파일에서만 답을 받아요.",
